import{_ as e,o as a,c as r,ai as d}from"./chunks/framework.ampVZV4B.js";const m=JSON.parse('{"title":"后端问题 · 分布式","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/problems/distributed.md","filePath":"tech-system/backend/problems/distributed.md"}'),s={name:"tech-system/backend/problems/distributed.md"};function i(l,t,n,h,o,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="后端问题-·-分布式" tabindex="-1">后端问题 · 分布式 <a class="header-anchor" href="#后端问题-·-分布式" aria-label="Permalink to “后端问题 · 分布式”">​</a></h1><h2 id="我怎么看「分布式」" tabindex="-1">我怎么看「分布式」 <a class="header-anchor" href="#我怎么看「分布式」" aria-label="Permalink to “我怎么看「分布式」”">​</a></h2><p>分布式不是荣誉称号。<br><strong>拆服务 = 用运维与一致性复杂度，换团队并行与规模。</strong></p><p>中小团队、MES、多数业务中台：我倾向 <strong>轻量单体 + 模块边界清晰</strong>。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to “常见坑”">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>常见根因</th><th>处理方向</th></tr></thead><tbody><tr><td>一拆就慢</td><td>网络调用变多、无超时</td><td>合并热点；超时与批量</td></tr><tr><td>数据对不齐</td><td>当本地事务用</td><td>最终一致；出箱/状态机</td></tr><tr><td>排障困难</td><td>无链路追踪</td><td>至少统一 requestId / 日志</td></tr><tr><td>为拆而拆</td><td>跟风微服务</td><td>先量痛点再拆</td></tr></tbody></table><h2 id="我的默认策略" tabindex="-1">我的默认策略 <a class="header-anchor" href="#我的默认策略" aria-label="Permalink to “我的默认策略”">​</a></h2><ul><li>配置中心、定时任务、缓存可以先「共享组件」，不等于要拆十几微服务</li><li>跨服务一致性：业务状态机 + 补偿，优先于上重型分布式事务</li><li>真要拆：按业务边界，不按技术时髦</li></ul><hr><p>Spring Cloud 组件「用过」与「该不该用」要分开讲，见 <a href="/my-vitepress-site/tech-system/backend/java/03-frameworks.html">Java · 03 框架与生态</a>。</p>',10)])])}const p=e(s,[["render",i]]);export{m as __pageData,p as default};
